$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const originalPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const aliasPath="references/instruction-wrapper-key-aliases.json";
const copyPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json";
const previousRunPath="workspaces/terminalruns/GPT6_0000000323_alias_inventory_retry-Terminals_20261109T192014334Z.json";
assert(fs.existsSync(originalPath),"Original draft is missing");
assert(!fs.existsSync(aliasPath),"Alias reference already exists; no overwrite");
assert(!fs.existsSync(copyPath),"Editable aliased copy already exists; no overwrite");
const raw=fs.readFileSync(originalPath,"utf8");
const original=JSON.parse(raw);
assert(Array.isArray(original)&&original.length>=2,"Unexpected template container");
assert(typeof original[0]==="object"&&!Array.isArray(original[0]),"Missing pinned explainer");
const occurrences=new Map();
function walk(value){
 if(Array.isArray(value)){for(const item of value)walk(item);return;}
 if(!value||typeof value!=="object")return;
 for(const [key,child] of Object.entries(value)){
  occurrences.set(key,(occurrences.get(key)||0)+1);
  walk(child);
 }
}
walk(original);
const keyToAlias=new Map(),aliasToKey=new Map();
const suffixAlphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
function allocate(key){
 if(keyToAlias.has(key))return keyToAlias.get(key);
 const first=key[0];
 assert(first&&first.length===1,"Unusable initial for "+key);
 let alias=first;
 if(aliasToKey.has(alias)){
  alias=null;
  for(const next of suffixAlphabet){
   const candidate=first+next;
   if(!aliasToKey.has(candidate)){alias=candidate;break;}
  }
 }
 assert(alias&&alias.length<=2&&alias[0]===first,"Alias exhausted for "+key);
 keyToAlias.set(key,alias);aliasToKey.set(alias,key);
 return alias;
}
for(const key of occurrences.keys())allocate(key);
assert.strictEqual(occurrences.size,103,"Source key inventory differs from prior verified draft");
assert.strictEqual([...keyToAlias.values()].filter(v=>v.length===1).length,22);
assert.strictEqual([...keyToAlias.values()].filter(v=>v.length===2).length,81);
assert(fs.existsSync(previousRunPath),"Prior alias inventory receipt absent");
const previousRun=JSON.parse(fs.readFileSync(previousRunPath,"utf8"));
const lines=previousRun.outputThat;
const begin=lines.indexOf("ALIAS_MAPPING_BEGIN"),end=lines.indexOf("ALIAS_MAPPING_END");
assert(begin>=0&&end>begin,"Prior inventory marker absent");
const prior=JSON.parse(lines.slice(begin+1,end).join("\n"));
assert.strictEqual(prior.number_of_unique_keys,103);
for(const row of prior.pairs){
 assert.strictEqual(keyToAlias.get(row.key),row.alias,"Prior alias assignment changed for "+row.key);
 assert.strictEqual(occurrences.get(row.key),row.occurrences,"Occurrence count changed for "+row.key);
}
const lookupMember="alias_lookup_path";
assert(!keyToAlias.has(lookupMember),"Unexpected lookup member in original");
const lookupAlias=allocate(lookupMember);
assert.strictEqual(lookupAlias,"ai","Expected next available same-initial alias");
const withLookup=structuredClone(original);
withLookup[0][lookupMember]=aliasPath;
function convert(value,mapping){
 if(Array.isArray(value))return value.map(item=>convert(item,mapping));
 if(value===null||typeof value!=="object")return value;
 const result={};
 for(const [key,child] of Object.entries(value)){
  const mapped=mapping.get(key);
  assert(mapped!==undefined,"Missing alias for "+key);
  assert(!Object.hasOwn(result,mapped),"Alias collision "+mapped);
  result[mapped]=convert(child,mapping);
 }
 return result;
}
const encoded=convert(withLookup,keyToAlias);
const decoded=convert(encoded,aliasToKey);
assert.deepStrictEqual(decoded,withLookup,"Aliased copy not losslessly reversible");
assert.deepStrictEqual(original,JSON.parse(raw),"Original draft changed in memory");
assert.strictEqual(encoded[0][lookupAlias],aliasPath,"Lookup pointer wrong");
const aliases=[...aliasToKey].map(([alias,key])=>({alias,key,occurrences:occurrences.get(key)||1}))
 .sort((x,y)=>x.alias.localeCompare(y.alias,"en"));
const aliasReference={
 title:"Account Custom Instruction Wrapper — Alias Lookup",
 applicability:"This reference defines a lossless, case-sensitive mapping of JSON object-member keys in the editable aliased copy of the account custom-instruction wrapper. It is not a substitute for the separately referenced structural rules or machine-dialect writing rules.",
 source_template_path:originalPath,
 aliased_template_copy_path:copyPath,
 alias_lookup_path:aliasPath,
 mapping_semantics:{
  keys:"Each distinct object-member key appearing anywhere in the source JSON has exactly one alias, including member keys in nested objects and objects inside arrays. The same original name is always encoded by the same alias.",
  first_character:"The first character of every alias must equal the exact first character of its original key, preserving capitalization.",
  allocation:"Assign one-character aliases first, one per distinct first character. For subsequent keys sharing that first character, allocate the shortest available two-character alias using suffixes a-z, then A-Z, then 0-9. Record assignments in depth-first, first-seen order.",
  data_preservation:"Replace JSON object-member keys only. Preserve all array positions, strings, numbers, booleans, nulls, object relationships, and rule bodies without modification.",
  additional_lookup_member:"The editable copy adds alias_lookup_path to its outer index-zero explainer. This new key is represented by alias ai. All 103 previously verified assignments remain unchanged.",
  decoding:"For every aliased object member, replace its alias with the matching original key from alias_to_key. Apply recursively through objects and arrays. The result is the source wrapper plus its new alias_lookup_path member."
 },
 source_template_sha256:crypto.createHash("sha256").update(raw).digest("hex"),
 original_key_count:occurrences.size,
 total_key_count_including_lookup:aliases.length,
 aliases_with_one_character:aliases.filter(x=>x.alias.length===1).length,
 aliases_with_two_characters:aliases.filter(x=>x.alias.length===2).length,
 alias_to_key:Object.fromEntries(aliases.map(x=>[x.alias,x.key]))
};
const readable=JSON.stringify(aliasReference,null,2)+"\n";
const copyText=JSON.stringify(encoded);
fs.writeFileSync(aliasPath,readable,"utf8");
fs.writeFileSync(copyPath,copyText+"\n","utf8");
assert.deepStrictEqual(JSON.parse(fs.readFileSync(aliasPath,"utf8")).alias_to_key,aliasReference.alias_to_key);
assert.deepStrictEqual(JSON.parse(fs.readFileSync(copyPath,"utf8")),encoded);
assert.deepStrictEqual(convert(JSON.parse(fs.readFileSync(copyPath,"utf8")),new Map(Object.entries(aliasReference.alias_to_key))),withLookup);
assert.strictEqual(fs.readFileSync(originalPath,"utf8"),raw,"Original wrapper draft mutated");
console.log("REFERENCE_PATH",aliasPath);
console.log("EDITABLE_ALIASED_COPY",copyPath);
console.log("ALIASES",aliases.length,"PRESERVED_EXISTING",occurrences.size);
console.log("SINGLE_CHAR",aliasReference.aliases_with_one_character,"TWO_CHAR",aliasReference.aliases_with_two_characters);
console.log("ALIAS_LOOKUP_MEMBER",lookupMember,"AS",lookupAlias);
console.log("ORIGINAL_BYTES",Buffer.byteLength(raw),"COPY_BYTES",Buffer.byteLength(copyText));
console.log("COPY_REVERSIBLE",true,"ORIGINAL_UNCHANGED",true);

NODE
git add -- 'references/instruction-wrapper-key-aliases.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json'
git diff --cached --check
git commit -m 'Add reversible key aliases and editable aliased instruction wrapper copy'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
